import clsx from 'clsx';
import React, { forwardRef } from 'react';

import { _useSharedProgressBarPropsContext } from './hooks/useProgressBarPropsContext.js';
import { progressBarIconContainerCSS } from './ProgressBarIcon.sty.js';
import type { DataTestId } from '../../types/data-props.js';
import type { StylingProps } from '../../types/styling-props.js';
import type { WithChildren } from '../../types/with-children.js';

/** Accepted properties for ProgressBarIcon */
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface ProgressBarIconProps
  extends WithChildren,
    StylingProps,
    DataTestId {}

/** ProgressBarIcon sub-component is renderd inside ProgressBar component. */
export const ProgressBarIcon = forwardRef<HTMLDivElement, ProgressBarIconProps>(
  (props, forwardedRef) => {
    const {
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: ProgressBarIconProps = props;
    const { variant } = _useSharedProgressBarPropsContext();

    return (
      <div
        data-testid={dataTestId}
        ref={forwardedRef}
        className={clsx(
          consumerClassName,
          progressBarIconContainerCSS({ variant }),
        )}
        style={consumerStyle}
        {...remainingProps}
      >
        {children}
      </div>
    );
  },
);

(
  ProgressBarIcon as typeof ProgressBarIcon & { displayName: string }
).displayName = 'ProgressBar.Icon';
